import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsv(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n') ||
    value.includes('\r')
  ) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: admin role required to export');
  }

  const tasks = Array.from(
    (taskManager as unknown as { tasks: Map<string, unknown> }).tasks.values()
  ) as ReturnType<typeof taskManager.getTask> extends null ? never : import('./tasks.js').Task[];

  // Access the internal task map via the known structure
  const allTasks: import('./tasks.js').Task[] = [];
  for (const t of (taskManager as { getTask: (id: string) => import('./tasks.js').Task | null })['getTask']('__list_all__') as any) {
    // We'll use a different approach – iterate the store directly
  }

  // Use a public-list-like iteration: we know tasks.ts keeps `tasks` private,
  // but `listByUser` is public and returns tasks for a given user.
  // To export *all* tasks we need a different approach: read them via the class.
  // Since we cannot access the private `tasks` map, we add a listAll helper.
  // Actually we can just re-query: collect all tasks by querying with a broad filter.
  // Simpler: add a listAll method or expose it. For now we iterate by using the fact
  // that task IDs are stored as keys and we have getTask which hits the cache.
  // But the cleanest way without modifying the public interface: call listByUser for
  // every known user ID – that's not practical. Instead we'll import the class.

  // We'll use a workaround: cast to any to access the private tasks map
  const taskMap = (taskManager as any).tasks as Map<string, import('./tasks.js').Task>;
  const all = Array.from(taskMap.values());

  record({
    action: 'export',
    userId,
    details: `exported ${all.length} tasks`,
    timestamp: Date.now(),
  });

  const header = 'id,title,status,assignee,createdAt';
  const rows = all.map(
    (t) =>
      `${escapeCsv(t.id)},${escapeCsv(t.title)},${escapeCsv(t.status)},${escapeCsv(t.assignee)},${t.createdAt}`
  );
  return [header, ...rows].join('\n');
}
