import { canDelete, canExport } from './permissions.js';
import { Cache } from './cache.js';
import { record, list, clear as clearAuditFn } from './audit.js';
import { exportTasks } from './exporter.js';

export function createUser(user: { id: string; name: string; role: 'user' | 'admin' }) {
  return createUserFn(user);
}

export function clearUsers() {
  clearUsersFn();
}

export function clearAudit() {
  clearAuditFn();
}

export { taskManager };
export { findById };
export { canDelete, canExport };
export { Cache };
export { record, list };
